"""客服 Agent 主流程：模型选择工具 -> 执行 -> 工具结果回填模型 -> 生成回答。"""

import re
from datetime import datetime, timedelta, timezone

from model_client import ModelClient
from patient_store import SESSION, find_by_identifier, resolve_authorized_patient
from tools.appointments import list_appointments
from tools.bills import list_bills
from tools.medications import list_medications
from tools.patient_profile import patient_profile

TOOLS = {
    "patient_profile": patient_profile,
    "list_medications": list_medications,
    "list_bills": list_bills,
    "list_appointments": list_appointments,
}

IDENTIFIER = re.compile(
    r"(?<![0-9０-９])"
    r"(?:(?:[0-9０-９][ 　－-]?){17}[0-9０-９XxＸｘ]|[1１](?:[ 　－-]?[0-9０-９]){10})"
    r"(?![0-9０-９])"
)
IDENTIFIER_WIDTH = str.maketrans("０１２３４５６７８９Ｘｘ　－", "0123456789Xx -")
HOSPITAL_TIMEZONE = timezone(timedelta(hours=8))


def _identifier_value(match):
    return match.group().translate(IDENTIFIER_WIDTH).replace(" ", "").replace("-", "").upper()


def _redact(value):
    if isinstance(value, str):
        def mask(match):
            identifier = _identifier_value(match)
            if len(identifier) == 11:
                return f"{identifier[:3]}****{identifier[-4:]}"
            return "[证件号已隐藏]"

        return IDENTIFIER.sub(mask, value)
    if isinstance(value, dict):
        return {_redact(key): _redact(item) for key, item in value.items()
                if key != "id_card"}
    if isinstance(value, list):
        return [_redact(item) for item in value]
    return value


class CustomerServiceAgent:
    def __init__(self, model_client=None):
        self.model = model_client or ModelClient()
        self.last_result = None
        self._login_ref = None
        self._patient_ref = None
        self._appointment_result = None

    def _system_message(self):
        today = datetime.now(HOSPITAL_TIMEZONE).date().isoformat()
        return {
            "role": "system",
            "content": (
                f"你是医院客服助手。今天是 {today}（北京时间）。根据患者问题选择工具。"
                "患者身份由服务端提供，无需传 patient_ref。"
                "查询预约使用 list_appointments，可传 date（YYYY-MM-DD）和 department（科室全称）。"
                "追问上一轮第几条预约时，只传从 1 开始的整数 index。"
                "预约列表按工具返回顺序编号。工具返回后用中文回答，不要编造信息。"
            ),
            "tools": sorted(TOOLS),
        }

    def answer(self, user_text):
        login_ref = SESSION["login_patient_ref"]
        if login_ref != self._login_ref:
            self._login_ref = login_ref
            self._patient_ref = None
            self._appointment_result = None
            self.last_result = None

        identifiers = {_identifier_value(match) for match in IDENTIFIER.finditer(user_text)}
        if identifiers:
            self._patient_ref = None
            self._appointment_result = None
            self.last_result = None
            refs = {find_by_identifier(identifier) for identifier in identifiers}
            if None in refs or len(refs) != 1:
                return "无法确定要查询的患者，请核对手机号或证件号。"
            self._patient_ref = refs.pop()

        patient_ref = self._patient_ref or login_ref
        try:
            resolve_authorized_patient(patient_ref)
        except (PermissionError, KeyError):
            self._appointment_result = None
            self.last_result = None
            return "当前登录身份无法查询该患者。"

        messages = [
            self._system_message(),
            {"role": "user", "content": _redact(user_text)},
        ]
        first = self.model.send(messages)
        if not isinstance(first, dict) or "tool" not in first:
            return _redact(first) if isinstance(first, str) else "请说明您想查询的内容。"

        name = first["tool"]
        if not isinstance(name, str) or name not in TOOLS:
            return "暂不支持该查询。"
        model_args = first.get("arguments") or {}
        if not isinstance(model_args, dict):
            return "请重新说明查询条件。"
        arguments = {"patient_ref": patient_ref}

        try:
            if name == "list_appointments" and "index" in model_args:
                index = model_args["index"]
                rows = (self._appointment_result or {}).get("appointments", [])
                if type(index) is not int or not 1 <= index <= len(rows):
                    return "上一轮预约结果中没有这条记录，请先查询预约列表。"
                arguments["index"] = index
                result = {"index": index, "appointment": rows[index - 1]}
            else:
                filters = {
                    "list_appointments": ("date", "department"),
                    "patient_profile": ("field",),
                }.get(name, ())
                for key in filters:
                    value = model_args.get(key)
                    if isinstance(value, str) and value.strip():
                        arguments[key] = value.strip()
                result = TOOLS[name](**arguments)
                if name == "list_appointments":
                    self._appointment_result = result
        except (PermissionError, KeyError):
            return "当前登录身份无法查询该患者。"

        self.last_result = _redact(result)
        response = self.model.send(messages + [
            {"role": "assistant", "tool_call": {"name": name, "arguments": _redact(arguments)}},
            {"role": "tool", "name": name, "content": self.last_result},
        ])
        return _redact(response) if isinstance(response, str) else "暂时无法生成查询结果。"
"""模型客户端：本机演示写请求日志，不访问外网。"""

import json
import os
import re
from datetime import date, timedelta

EVIDENCE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "evidence")
REQUEST_LOG = os.path.join(EVIDENCE_DIR, "model-requests.jsonl")


class ModelClient:
    def __init__(self, log_path=None):
        self.log_path = log_path or REQUEST_LOG

    def send(self, messages):
        os.makedirs(os.path.dirname(self.log_path), exist_ok=True)
        with open(self.log_path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"event": "model_request", "messages": messages},
                                ensure_ascii=False) + "\n")
        if messages[-1]["role"] == "user":
            return self._choose_tool(messages)
        if messages[-1]["name"] == "list_appointments":
            return self._format_appointments(messages[-1]["content"], messages[1]["content"])
        return "已为您查询。"

    def _choose_tool(self, messages):
        """模拟本机演示所需的预约意图和参数。"""
        user_text = messages[-1]["content"]
        ordinal = re.search(r"第([0-9]+|[一二三四五六七八九十两])条", user_text)
        if ordinal and ("科室" in user_text or "预约" in user_text):
            number = ordinal[1]
            index = int(number) if number.isascii() else "〇一二三四五六七八九十".index(
                number.replace("两", "二")
            )
            return {"tool": "list_appointments", "arguments": {"index": index}}

        if "预约" not in user_text and "挂号" not in user_text:
            return {"tool": "patient_profile", "arguments": {}}

        arguments = {}
        explicit_date = re.search(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", user_text)
        relative_date = re.search(r"今天|明天|后天|昨天", user_text)
        if explicit_date:
            arguments["date"] = explicit_date[0]
        elif relative_date:
            today = date.fromisoformat(re.search(
                r"今天是 ([0-9]{4}-[0-9]{2}-[0-9]{2})", messages[0]["content"]
            )[1])
            offset = {"今天": 0, "明天": 1, "后天": 2, "昨天": -1}[relative_date[0]]
            arguments["date"] = (today + timedelta(days=offset)).isoformat()

        department = re.search(r"口腔科|内科", user_text)
        if department:
            arguments["department"] = department[0]
        return {"tool": "list_appointments", "arguments": arguments}

    def _format_appointments(self, result, user_text):
        if "appointment" in result:
            row = result["appointment"]
            if "科室" in user_text:
                return f"第{result['index']}条预约的科室是{row['department']}。"
            return self._format_row(result["index"], row)
        return "\n".join(self._format_row(index, row)
                         for index, row in enumerate(result["appointments"], 1)) or "未查到符合条件的预约。"

    def _format_row(self, index, row):
        return f"{index}. {row['date']} {row['time']} {row['department']}（{row['status']}）"
"""患者身份：以手机号或身份证号作为唯一键。"""

PATIENTS = {
    "P7": {"patient_id": 7001, "name": "张三丰(虚构)",
           "phone": "13900001234", "id_card": "110105199003074219"},
    "P8": {"patient_id": 7002, "name": "李四合(虚构)",
           "phone": "13800005678", "id_card": "310101198512061234"},
}

# 手机号 / 身份证号 -> patient_ref
_BY_PHONE = {p["phone"]: ref for ref, p in PATIENTS.items()}
_BY_ID_CARD = {p["id_card"]: ref for ref, p in PATIENTS.items()}

# 登录人（P7）与其已授权家属
SESSION = {"login_patient_ref": "P7", "authorized_refs": {"P7", "P8"}}


def find_by_identifier(value):
    """用手机号或身份证号定位 patient_ref；找不到返回 None。"""
    if not isinstance(value, str):
        return None
    value = value.strip()
    return _BY_PHONE.get(value) or _BY_ID_CARD.get(value)


def resolve_authorized_patient(patient_ref):
    if patient_ref not in SESSION["authorized_refs"]:
        raise PermissionError(f"当前登录身份无权访问 {patient_ref}")
    return PATIENTS[patient_ref]["patient_id"]
